KEY=$(grep -oE '"key":"[^"]+"' .firecrawl/yc-raw.html | cut -d'"' -f4); 
U="https://45BWZJ1SGC-dsn.algolia.net/1/indexes/YCCompany_production?x-algolia-application-id=45BWZJ1SGC&x-algolia-api-key=$KEY&query=&hitsPerPage=1&facets=%5B%22*%22%5D&maxValuesPerFacet=1000"
firecrawl scrape "$U" --max-age 0 --format rawHtml -o .firecrawl/alg-facets.json; python3 -I -c "
import json;d=json.loads(json.load(open('.firecrawl/alg-facets.json'))['rawHtml'])
print(d['nbHits']);f=d['facets'];print(list(f));
for k in f:
  if 'batch' in k or 'industr' in k or 'subindustr' in k or 'tag' in k: print(k,{a:b for a,b in f[k].items() if '2025' in a or 'Developer' in a or 'Dev' in a})
print(json.dumps(d['hits'][0],indent=0)[:3000])"

